1345	    const int tid = threadIdx.x;
1346	    if (tid == 0) {
1347	#pragma unroll
1348	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], USE_TMA ? 1 : NumProd); mbar_init(&empty[s], NCONS); }
1349	#pragma unroll
1350	        for (int s = 0; s < QBUF; ++s) { mbar_init(&barQf[s], (tmaq || tmaq_gqa) ? 1 : NumProd); mbar_init(&barQe[s], NCONS); }
1351	#pragma unroll
1352	        for (int s = 0; s < SDEPTH; ++s) { mbar_init(&schF[s], 1); mbar_init(&schE[s], NCONS); }
1353	    }
1354	    __syncthreads();
1355	
1356	    // Dynamic LPT-free balancing: instead of static work=blockIdx.x+k*gridDim.x (which strands the
1357	    // causal triangular load -- early m-tiles are light, late ones heavy -- on fixed CTAs), each CTA
1358	    // pulls the next tile from a global atomic counter. The producer's lead thread grabs + publishes the
1359	    // index through a tiny smem FIFO (schW/schF/schE) so both warpgroups process the SAME stream while
1360	    // the GPU load-balances across CTAs the way the HW block scheduler does for the per-tile grid.
1361	    const int total_work = tiles_m * hkv * batch;
1362	    const int wg = tid / WG;
1363	
1364	    if (wg == 0) {
1365	        // ---------- producer ----------
1366	        producer_regs();
1367	        const int pt = tid;
1368	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1369	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1370	        const int pages = np ? 0 : (CN / block_size);
1371	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1372	        int g = 0, witer = 0;
1373	        for (int it = 0; ; ++it) {
1374	            // Pull the next tile from the global atomic; pt==0 grabs + publishes via schW, the producer
1375	            // warpgroup broadcasts it (bar.sync), and pt==0 signals schF for the consumers.
1376	            const int sslot = it % SDEPTH;
1377	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1378	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1379	            asm volatile("bar.sync 1, %0;\n" :: "r"(WG) : "memory");
1380	            const int work = schW[sslot];
1381	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1382	            if (work >= total_work) break;
