1422	            //     signal. rep==1 reloads via ONE TMA box-set; GQA/paged fall back to the cp.async gather.
1423	            const int qslot = witer % QBUF;
1424	            const int qcyc = witer / QBUF;
1425	            TC* sQs = sQ + qslot * (CM * HDsm);
1426	            if (witer >= QBUF) { int p = (qcyc - 1) & 1; while (!mbar_try_wait(&barQe[qslot], p)) {} }
1427	            if (tmaq) {
1428	                if (pt == 0) {
1429	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1430	                    const int yq = t.q0 + t.row0, xq = t.hk * HD;  // rep==1 -> qhead == hk
1431	                    constexpr int QBOX = HD / 64;
1432	#pragma unroll
1433	                    for (int bx = 0; bx < QBOX; ++bx) tma_box(sQs + bx * (CM * 64), &mapQ, xq + bx * 64, yq, &barQf[qslot]);
1434	                }
1435	            } else if (tmaq_gqa) {
