1438	                    // 3D box: token z = q0 + row0/rep (rep|CM => row0/rep is the tile's first token),
1439	                    // head y = hk*rep, col x = bx*64. One box per col-block fills the [CM,64] swizzle tile.
1440	                    const int zq = t.q0 + t.row0 / rep, yq = t.hk * rep;
1441	                    constexpr int QBOX = HD / 64;
