1492	    constexpr bool PINGPONG = (CM == 128) && (HD == 128 || (HD == 192 && HDV == 128));
1493	    constexpr int PP_BASE = 8, PP_CNT = 2 * WG;   // barriers 8/9, 256 threads (both consumer WGs)
1494	    if constexpr (PINGPONG) { if (cwg == 0) nb_arrive(PP_BASE, PP_CNT); }  // WG0 issues first
