903	template <typename TIn, typename TC, int HD, int HDV, bool USE_TMA, bool EXTRA, int STAGES, int CN = CTA_N,
904	          int CM = CTA_M, int MINB = 1>
905	__global__ __launch_bounds__(WG * (1 + CM / 64), MINB) void prefill_kernel(
906	        const TIn* __restrict__ Q, const TIn* __restrict__ K,
907	        const TIn* __restrict__ V, TC* __restrict__ O, float* __restrict__ LSE,
908	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
909	        const int* __restrict__ page_table,
910	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
911	        int hkv, int rep, int total_q, int block_size, int page_stride,
912	        float scale, int causal, float softcap, int win_l, int win_r,
913	        int num_splits, float* __restrict__ Opart, float* __restrict__ LSEpart,
914	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
915	        const float* __restrict__ v_descale, int ds_b, int ds_h,
916	        const float* __restrict__ s_aux, const int* __restrict__ leftpad_k,
917	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapV) {
918	    constexpr bool CONV = !std::is_same<TIn, TC>::value;     // fp8 gmem -> bf16 smem (no TMA, convert-store)
919	    // Smem/compute dims are HD/HDV rounded UP to a multiple of 64 (the 128B-swizzle col-block width):
920	    // head dims that aren't a multiple of 64 (e.g. 96) pad the tile to the next 64 so the validated
921	    // koff/voff swizzle still applies. Loads fill only the real HD/HDV cols; the QK k-loop runs HD/16
922	    // (never touches the pad), and PV computes HDVsm/64 boxes (the pad cols land in discarded acc lanes).
923	    constexpr int HDsm  = ((HD  + 63) / 64) * 64;
924	    constexpr int HDVsm = ((HDV + 63) / 64) * 64;
925	    constexpr int KSTRIDE = CN * HDsm;         // one swizzled K tile (elems)
926	    constexpr int VSTRIDE = CN * HDVsm;        // one swizzled V tile (elems)
927	    // Consumer warpgroups = CM/64 (each WG does 64 q-rows). Decode passes CM=64 (1 consumer WG) so the
928	    // 2nd-warpgroup compute that would be entirely masked for tiny-M decode is never launched, and the
929	    // halved Q smem buys extra K/V pipeline stages (the memory-latency-hiding lever). Prefill: CM=128.
930	    constexpr int NCONS = (CM / 64) * WG;      // consumer thread count (empty[] barrier arrival count)
931	    const int m_block = blockIdx.x / num_splits, split = blockIdx.x % num_splits, hk = blockIdx.y, bi = blockIdx.z;
932	    const int q0 = cu_q[bi];
933	    const int seqlen_q = cu_q[bi + 1] - q0;
934	    const int seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
935	    const int Mrows = seqlen_q * rep;
936	    const int row0 = m_block * CM;
937	    if (row0 >= Mrows) return;                          // padded m_block (varlen/ragged): no valid rows
938	    const int delta = seqlen_k - seqlen_q;             // varlen causal append alignment
939	    // fp8 descale folding: Q,K,V are stored in smem as their RAW (fp8->bf16) values; the real values
940	    // are q*qd, k*kd, v*vd. exp(scale*Q_real.K_real) = exp((scale*qd*kd)*(q_raw.k_raw)) ⇒ fold qd*kd
941	    // into the softmax scale; v_descale is a constant factor ⇒ apply once to O at the epilogue.
942	    const long ds_idx = (long)bi * ds_b + (long)hk * ds_h;
943	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
944	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
945	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
946	    const float sc_eff = scale * qd * kd;
947	    const float s2 = sc_eff * float(M_LOG2E);
948	    const int lpad = leftpad_k ? leftpad_k[bi] : 0;    // cache_leftpad: ignore keys [0, lpad)
949	    const int top = (row0 + CM - 1 < Mrows - 1) ? (row0 + CM - 1) : (Mrows - 1);
950	    const int qabs_max = (top / rep) + delta;
951	    int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((seqlen_k + CN - 1) / CN);
952	    // Sliding-window tile pruning: tiles whose keys are entirely outside [qabs-win_l, qabs+win_r] for
953	    // every row are fully masked -> skip them. Left bound uses the CTA's smallest qabs (row 0), right
954	    // bound (non-causal) its largest. Cheap causal/non-SWA path keeps n_beg=0 / n_max unchanged.
955	    int n_beg = 0;
956	    if constexpr (EXTRA) {
957	        if (win_l >= 0) { int lo = (row0 / rep) + delta - win_l; if (lo > 0) n_beg = lo / CN; }
958	        if (!causal && win_r >= 0) { int t = (qabs_max + win_r) / CN + 1; if (t < n_max) n_max = t; }
959	        if (lpad > 0) { int lb = lpad / CN; if (lb > n_beg) n_beg = lb; }   // skip fully-leftpad tiles
960	    }
961	    // split-KV: this CTA processes the absolute key-tile range [n_lo, n_lo+n_cnt). Ring/barrier phases
962	    // use a LOCAL counter (0..n_cnt-1) so they start at parity 0; key offsets/masks use the absolute nb.
963	    // An empty CTA (empty KV, fully window-masked, or a split past the last tile) does no compute -- for
964	    // split-KV it stamps -inf into its LSEpart rows (so combine drops it) instead of relying on a host
965	    // pre-fill; single-split just exits. Detected uniformly, before the mbar_init/__syncthreads below.
966	    int n_lo = n_beg, n_cnt = n_max - n_beg;
967	    bool empty_cta = (seqlen_k <= 0) || (n_beg >= n_max);
968	    if (!empty_cta && num_splits > 1) {
969	        const int per = (n_max - n_beg + num_splits - 1) / num_splits;
970	        n_lo = n_beg + split * per;
971	        if (n_lo >= n_max) empty_cta = true;
972	        else n_cnt = (n_max - n_lo < per) ? (n_max - n_lo) : per;
973	    }
974	    if (empty_cta) {
975	        if (num_splits > 1)
976	            emit_empty_lse(LSEpart, (int)threadIdx.x, split, hkv * rep, row0, Mrows, hk, rep, q0, total_q);
977	        else
978	            emit_zero_o<TC, HDV>(O, LSE, (int)threadIdx.x, row0, Mrows, hk, rep, q0, total_q, o_row, o_head);
979	        return;

