2293	        page_table, mapK, mapV, hkv, rep, total_q, block_size, page_stride,                             \
2294	        (max_seqlen_q * rep + (CM_) - 1) / (CM_), b, scale,                                             \
2295	        causal, softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,      \
2296	        1, nullptr, nullptr, qd, kd, vd, ds_b, ds_h, s_aux, nullptr, stream)
2297	#define PF_DISPATCH(HD_, HDV_, ST_, CN_, CM_)                                                           \
2298	    do {                                                                                                \
2299	        bool extra = (softcap > 0.0) || (win_l >= 0) || (win_r >= 0);                                   \
