2319	    // hd192->dv128 (FA3 flash_fwd_hdimdiff): CN=128/STAGES=2 (FA3's exact tile) halves the barrier
2320	    // crossings of the old CN=64/STAGES=4 (barrier-stall-bound, DRAM only ~21%); smem-neutral (208KB
2321	    // both) and CN=128 is the validated swizzle width. cn_eff above is made hdv-aware for the TMA map.
2322	    else if (hd == 192 && hdv == 128) PF_DISPATCH(192, 128, 2, 128, 128);
