2336	// Native fp8 (e4m3) prefill launcher (output bf16). Mirrors launch_prefill but routes to
2337	// prefill_fp8_kernel: no TMA, V is transposed in-kernel, P round-trips through smem for SS PV.
2338	template <int HD, int HDV, bool EXTRA, int STAGES = WS_STAGES>
2339	static void launch_prefill_fp8_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2340	                                 at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2341	                                 const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2342	                                 const std::optional<at::Tensor>& page_table, int hkv, int rep, int total_q,
2343	                                 int block_size, int page_stride, int tiles_m, int b, double scale, bool causal,
2344	                                 double softcap, int win_l, int win_r,
2345	                                 long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2346	                                 long o_row, long o_head, int num_splits, float* Opart, float* LSEpart,
2347	                                 const float* qd, const float* kd, const float* vd, int ds_b, int ds_h,
2348	                                 cudaStream_t stream) {
2349	    const bool paged = page_table.has_value();
2350	    // Persistent continuous-ring fp8 prefill: collapses the per-tile grid's ~8.7 waves into 1 (the fp8
2351	    // dense config's 38% long_scoreboard was the per-CTA cold-start that the streamed K/V ring hides).
2352	    // (A deeper PSTG=4 ring fits at 1-byte fp8 -- 16384*14=224KB -- but only moved 0.817->0.820, so the
2353	    // remaining gap is the SS-PV smem round-trip / V-transpose, not ring depth; kept at STAGES=3.)
2354	    // Scoped to non-paged + num_splits==1 (paged/split/varlen stay on the per-tile grid below).
2355	    if (!paged && num_splits <= 1) {
2356	        static int num_sm = 0;
2357	        if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
2358	        const long total_work = (long)tiles_m * hkv * b;
2359	        if (total_work >= 2L * num_sm) {
2360	            constexpr int QBUF = 1, SDEPTH = 2;   // must match prefill_fp8_persist_kernel
2361	            constexpr int HDQK = (HD < 128) ? 128 : HD;   // K/Q 128-wide (koff8 row*128); see fp8 kernel
2362	            int smem_p = (int)(QBUF * CTA_M * HDQK + STAGES * CTA_N * HDQK + STAGES * HDV * CTA_N + CTA_M * CTA_N
2363	                               + STAGES * CTA_N * HDV)
2364	                         + (3 * STAGES + 2 * QBUF + 2 * SDEPTH) * (int)sizeof(uint64_t) + SDEPTH * (int)sizeof(int);
2365	            auto wctr = at::empty({1}, q.options().dtype(at::kInt));
2366	            cudaMemsetAsync(wctr.data_ptr<int>(), 0, sizeof(int), stream);
2367	            // fp8 TMA maps: K swizzled (koff8, [128,CTA_N] box) + V-staging plain ([128,CTA_N], no swz).
2368	            // Requires contiguous heads (stride(1)==hd). Falls back below if not TMA-eligible.
2369	            const bool fp8_tma_ok = (HD == 128 && HDV == 128) &&
2370	                                    (k.stride(2) == 1 && v.stride(2) == 1 &&
2371	                                     k.stride(1) == (int64_t)HD && v.stride(1) == (int64_t)HDV);
2372	            if (fp8_tma_ok) {
2373	                CUtensorMap mapK = make_fp8_contig(k, CTA_N, true);
2374	                CUtensorMap mapVst = make_fp8_contig(v, CTA_N, false);
2375	                static bool attr_set_p = false;
2376	                if (!attr_set_p) { cudaFuncSetAttribute(prefill_fp8_persist_kernel<HD, HDV, EXTRA, STAGES>, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_p); attr_set_p = true; }
2377	                const unsigned gx = (unsigned)(total_work < (long)num_sm ? total_work : (long)num_sm);

2603	//   * warp 0 builds the per-split softmax weights in smem (num_splits <= 64).
2604	//   * the split loop is unrolled x4 with 4 independent accumulators -> 4 O loads in flight/thread
2605	//     (memory-level parallelism), the real lever on a latency-bound reduce.
2606	constexpr int COMBINE_THREADS = 128;
2607	constexpr int combine_nb(int hdv) { return hdv / 64 > 0 ? hdv / 64 : 1; }
2608	template <typename TOut, int HDV>
2609	__global__ __launch_bounds__(COMBINE_THREADS) void combine_kernel(
2610	        const float* __restrict__ Opart, const float* __restrict__ LSEpart,
2611	        TOut* __restrict__ O, float* __restrict__ LSE,
2612	        int num_splits, int total_q, int hq, long o_row, long o_head) {
2613	    constexpr int NB = combine_nb(HDV);
2614	    constexpr int TILE = HDV / NB;
2615	    const int witem = blockIdx.x;
2616	    if (witem >= total_q * hq) return;
2617	    const int qidx = witem / hq, head = witem % hq;
2618	    const int tile = blockIdx.y, e0 = tile * TILE;
2619	    const int tid = threadIdx.x;
2620	
2621	    __shared__ float sw[64];          // per-split softmax weight (num_splits <= 64)
2622	    __shared__ float s_inv, s_lse;
2623	    if (tid < 32) {                   // warp 0: lmax -> weights -> denom
2624	        float lmax = -INFINITY;
2625	        for (int s = tid; s < num_splits; s += 32)
2626	            lmax = fmaxf(lmax, LSEpart[((long)s * hq + head) * total_q + qidx]);
2627	#pragma unroll
2628	        for (int o = 16; o > 0; o >>= 1) lmax = fmaxf(lmax, __shfl_xor_sync(0xffffffffu, lmax, o));
2629	        float denom = 0.f;
2630	        for (int s = tid; s < num_splits; s += 32) {
2631	            float lse = LSEpart[((long)s * hq + head) * total_q + qidx];
2632	            float w = (lmax > -INFINITY) ? __expf(lse - lmax) : 0.f;
2633	            sw[s] = w;
2634	            denom += w;
2635	        }
2636	#pragma unroll
2637	        for (int o = 16; o > 0; o >>= 1) denom += __shfl_xor_sync(0xffffffffu, denom, o);
2638	        if (tid == 0) { s_inv = denom > 0.f ? 1.f / denom : 0.f;
2639	                        s_lse = denom > 0.f ? (lmax + __logf(denom)) : -INFINITY; }
2640	    }
2641	    __syncthreads();
2642	    const float inv = s_inv;
2643	    const float* base = Opart + (((long)qidx * hq + head) * HDV);   // + s*sstride + e
2644	    const long sstride = (long)total_q * hq * HDV;
2645	    TOut* o = O + (long)qidx * o_row + (long)head * o_head;
2646	    // A zero-weight split contributes nothing -- but an EMPTY split (num_splits not dividing the
2647	    // key-tile count -> a trailing split starts past the last tile) never writes its Opart slice, so
2648	    // that memory is uninitialized at::empty (clean zeros on a fresh alloc, but NaN/inf when the
2649	    // caching allocator recycles a dirty pool). w==0 must therefore yield exactly 0, NOT 0*Opart
2650	    // (0*NaN=NaN). The select gates the garbage out; non-empty splits always store finite Opart.
2651	    for (int e = e0 + tid; e < e0 + TILE; e += COMBINE_THREADS) {
2652	        float a0 = 0.f, a1 = 0.f, a2 = 0.f, a3 = 0.f;
2653	        int s = 0;
2654	        for (; s + 4 <= num_splits; s += 4) {
2655	            float w0 = sw[s + 0], w1 = sw[s + 1], w2 = sw[s + 2], w3 = sw[s + 3];
2656	            a0 += w0 != 0.f ? w0 * base[(long)(s + 0) * sstride + e] : 0.f;
2657	            a1 += w1 != 0.f ? w1 * base[(long)(s + 1) * sstride + e] : 0.f;
2658	            a2 += w2 != 0.f ? w2 * base[(long)(s + 2) * sstride + e] : 0.f;
2659	            a3 += w3 != 0.f ? w3 * base[(long)(s + 3) * sstride + e] : 0.f;
2660	        }
2661	        float acc = (a0 + a1) + (a2 + a3);
2662	        for (; s < num_splits; ++s) { float w = sw[s]; acc += w != 0.f ? w * base[(long)s * sstride + e] : 0.f; }
2663	        o[e] = from_float<TOut>(acc * inv);
2664	    }
2665	    if (tid == 0 && tile == 0) LSE[(long)head * total_q + qidx] = s_lse;
2666	}
