2669	static void launch_decode_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2670	                            at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2671	                            const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2672	                            const std::optional<at::Tensor>& page_table,
2673	                            const std::optional<at::Tensor>& qd, const std::optional<at::Tensor>& kd,
2674	                            const std::optional<at::Tensor>& vd,
2675	                            int b, int hq, int hkv, int total_q, int cfg_splits, double scale,
2676	                            double softcap, int win_l, int win_r, bool causal, int max_klen, cudaStream_t stream) {
2677	    const bool paged = page_table.has_value();
2678	    int rep = hq / hkv;
2679	    long q_row = q.stride(0), q_head = q.stride(1);
2680	    long k_row, k_head, v_row, v_head;
2681	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2682	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2683	    long o_row = out.stride(0), o_head = out.stride(1);
