2685	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2686	
2687	    // num_splits: forced when cfg>0, else split aggressively for occupancy (this warp path is 1 warp /
2688	    // work-item, so more splits = more resident warps). Don't split finer than 64 keys/split.
2689	    int num_splits;
2690	    if (cfg_splits > 0) num_splits = cfg_splits;
2691	    else {
2692	        int dev = 0; cudaGetDevice(&dev);
2693	        int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2694	        int base = hkv * b;
2695	        int want = (8 * sms * WARPS_PER_BLOCK + base - 1) / (base > 0 ? base : 1);
