2703	    at::Tensor LSEpart = at::empty({(long)num_splits, hq, total_q}, fopt);
2704	
2705	    int witems = num_splits * hkv * b;
2706	    int blocks = (witems + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
2707	    dim3 grid((unsigned)blocks, 1, 1);
2708	    decode_kernel<TIn, TOut, HD, HDV, MAXM><<<grid, DEC_THREADS, 0, stream>>>(
2709	        (const TIn*)q.data_ptr(), (const TIn*)k.data_ptr(), (const TIn*)v.data_ptr(),
2710	        (float*)Opart.data_ptr(), (float*)LSEpart.data_ptr(),
2711	        (const int*)cu_q.data_ptr(), cu_k ? (const int*)cu_k->data_ptr() : nullptr,
2712	        seqused_k ? (const int*)seqused_k->data_ptr() : nullptr,
2713	        paged ? (const int*)page_table->data_ptr() : nullptr,
2714	        qd ? (const float*)qd->data_ptr() : nullptr, kd ? (const float*)kd->data_ptr() : nullptr,
2715	        vd ? (const float*)vd->data_ptr() : nullptr, ds_b, ds_h,
2716	        q_row, q_head, k_row, k_head, v_row, v_head,
2717	        b, hq, hkv, rep, total_q, block_size, page_stride, num_splits,
2718	        (float)scale, (float)softcap, win_l, win_r, causal ? 1 : 0);
2719	
2720	    combine_kernel<TOut, HDV><<<dim3((unsigned)(total_q * hq), (unsigned)combine_nb(HDV)), COMBINE_THREADS, 0, stream>>>(
2721	        (const float*)Opart.data_ptr(), (const float*)LSEpart.data_ptr(),
2722	        (TOut*)out.data_ptr(), (float*)lse.data_ptr(), num_splits, total_q, hq, o_row, o_head);
2723	}
