2867	        mapK, mapV, hkv, rep, total_q, block_size, page_stride, tiles_m, b, scale, causal,              \
2868	        softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head, NS_, OP_, LP_, \
2869	        qd, kd, vd, ds_b, ds_h, nullptr, leftpad_k, stream)
