2874	    do { if (deep) { if (extra) DS_BY_TMA(true, DCN_D, DST_D, DCM_DEEP, MINB_D, NS_, OP_, LP_); else DS_BY_TMA(false, DCN_D, DST_D, DCM_DEEP, MINB_D, NS_, OP_, LP_); } \
2875	         else      { if (extra) DS_BY_TMA(true, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); else DS_BY_TMA(false, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); } } while (0)
