580	// ============================ native fp8 (e4m3) prefill path ============================
581	// QK and PV both run on the fp8 tensor core (2x bf16 throughput). The f32 accumulator layout for
582	// m64n128k32.e4m3 is identical to the bf16 m64n128k16 one, so softmax/mask/epilogue are unchanged.
583	// fp8 1-byte 128B swizzle: 128 fp8 = one 128B row; the 16-byte (16-fp8) chunk is swizzled by row&7.
584	// For hd128/CTA_N=128 every operand tile (Q,K,Vt,P) is a [128-row,128-col] K-major fp8 tile. The
585	// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
586	// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
587	__device__ __forceinline__ int koff8(int row, int c) {
588	    return (c >> 7) * (128 * CTA_N) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
589	}
590	constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
591	__device__ __forceinline__ void wg_barrier(int id) {
592	    asm volatile("bar.sync %0, 128;\n" :: "r"(id) : "memory");
593	}
594	// FA3 warp-scheduler ping-pong primitives (mainloop_fwd_sm90_tma_gmma_ws.hpp). A named barrier with
595	// an explicit arrival count: one consumer WG `bar.sync`s it (contributes its 128 threads + blocks)
596	// while the other WG `bar.arrive`s it (contributes 128, no block). With cnt = 256 the syncing WG
597	// unblocks only once the other WG arrives -> the two consumer WGs alternate their wgmma-issue phase
598	// by one step, so while WG_a runs softmax on the SFU, WG_b feeds the tensor core (and vice-versa).
599	__device__ __forceinline__ void nb_sync(int id, int cnt) {
600	    asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
601	}
602	__device__ __forceinline__ void nb_arrive(int id, int cnt) {
603	    asm volatile("bar.arrive %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
604	}
605	// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
606	template <int HDt>
607	__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
608	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
609	#pragma unroll
610	    for (int kb = 0; kb < HDt / 32; ++kb) {
611	        uint32_t off = (uint32_t)(kb * 32);
612	        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
613	        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
614	        int scaleD = (kb == 0) ? 0 : 1;
615	        asm volatile(
616	        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
617	        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
618	        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
619	    }
620	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
621	}
622	// PV: acc_o[HDV/2] += P.V (e4m3 SS over CTA_N keys; A=P[q][key], B=Vt[dv][key]). m64n128 for HDV=128,
623	// m64n64 for HDV=64 (hd64 fp8 decode -- acc_o[32]). The Vt koff8 layout + SW8 descriptor are HDV-agnostic
624	// (only the dv-row count differs), so n is the only change. Always accumulates (running online output).
625	template <int HDV>
626	__device__ __forceinline__ void pv_fp8_ss(float (&acc_o)[HDV/2], uint32_t sP_wg, uint32_t sV_base) {
627	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
628	#pragma unroll
629	    for (int kb = 0; kb < CTA_N / 32; ++kb) {
630	        uint32_t off = (uint32_t)(kb * 32);
631	        uint64_t dA = make_smem_desc(sP_wg + off, SW8_LBO, SW8_SBO, 1);
632	        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
633	        if constexpr (HDV == 128)
634	            asm volatile(
635	            "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
636	            "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
637	            : PF_OUT64(acc_o) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
638	        else
639	            asm volatile(
640	            "{\n.reg .pred p;\n setp.ne.b32 p, %34, 0;\n"
641	            "wgmma.mma_async.sync.aligned.m64n64k32.f32.e4m3.e4m3 " PF_ACC32 ",%32,%33,p,%35,%36;\n}\n"
642	            : PF_OUT32(acc_o, 0) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
643	    }
644	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
645	}
646	// FA3 register-source P (MmaPV_is_RS): build the fp8 A-operand registers from the f32 softmax
647	// probabilities s[64] (C-accumulator layout) WITHOUT the smem scatter+barrier round-trip. Pack each
648	// c-group's 4 f32 ((p,r2) combined, convert_layout_acc_Aregs order) -> P16[c], then permute_Aregs_fp8
649	// (quad __shfl + byte_perm) fixes the register layout to the wgmma A operand. Validated bit-exact vs
650	// the SS path in kernels/fp8_probe.cu (PV-RS). tg=lane&3, group=lane>>2.
651	__device__ __forceinline__ void build_P_rs_fp8(const float (&s)[64], uint32_t (&P16)[16], int tg, int group) {
652	#pragma unroll
653	    for (int c = 0; c < 16; ++c) {
654	        __nv_fp8_e4m3 e0(s[c*4+0]), e1(s[c*4+1]), e2(s[c*4+2]), e3(s[c*4+3]);
655	        P16[c] = (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
656	    }
657	    const bool lane_03 = (tg == 0 || tg == 3);
658	    const int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
659	    const int up = (tg == 0) ? 0 : (tg == 1) ? 3 : (tg == 2) ? 1 : 2;   // upper_map[tg]
660	    const int src_hi = group * 4 + up, src_lo = group * 4 + (up ^ 1);
661	#pragma unroll
662	    for (int u = 0; u < 8; ++u) {
663	        uint32_t upper = P16[2*u + 0], lower = P16[2*u + 1];
664	        uint32_t upper0 = lane_03 ? upper : lower;
665	        uint32_t lower0 = lane_03 ? lower : upper;
666	        upper0 = __shfl_sync(0xffffffffu, upper0, src_hi, 32);
667	        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
668	        P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
669	        P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
670	    }
671	}
672	// PV with P in REGISTERS (RS A operand): acc_o += P.V over CTA_N keys, A = P16[4kb..4kb+3] per k-block,
673	// B = Vt[dv][key] (smem descriptor). No smem-P scatter/barrier -> enables the QK(i+1)/PV(i) pipeline.
674	// m64n128 for HDV=128, m64n64 for HDV=64 (acc_o[32]).
675	template <int HDV>
676	__device__ __forceinline__ void pv_fp8_rs(float (&acc_o)[HDV/2], const uint32_t (&P16)[16], uint32_t sV_base) {
677	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
678	#pragma unroll
679	    for (int kb = 0; kb < CTA_N / 32; ++kb) {
680	        uint32_t off = (uint32_t)(kb * 32);
681	        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
682	        if constexpr (HDV == 128)
683	            asm volatile(
684	            "{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
685	            "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
686	            : PF_OUT64(acc_o)
687	            : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
