699	// Two adjacent key-cols share a byte pair => one st.shared.u16 (koff8 is even at col=8c+2tg).
700	__device__ __forceinline__ void scatter_P_fp8(const float (&s)[64], uint32_t sP_wg_addr,
701	                                              int warp, int group, int tg) {
702	#pragma unroll
703	    for (int c = 0; c < CTA_N / 8; ++c)
704	#pragma unroll
705	        for (int r = 0; r < 2; ++r) {
706	            int row = warp * 16 + group + r * 8;
707	            int col = 8 * c + 2 * tg;
708	            __nv_fp8_e4m3 a(s[c*4+r*2+0]), b(s[c*4+r*2+1]);
709	            uint16_t packed = (uint16_t)a.__x | ((uint16_t)b.__x << 8);
710	            uint32_t dst = sP_wg_addr + (uint32_t)koff8(row, col);
711	            asm volatile("st.shared.u16 [%0], %1;\n" :: "r"(dst), "h"(packed) : "memory");
712	        }
