732	__device__ __forceinline__ void gather_row_plain8_cp(__nv_fp8_e4m3* sbase, uint32_t sbase_addr, int row,
733	                                                     const __nv_fp8_e4m3* src, bool valid) {
734	#pragma unroll
735	    for (int c16 = 0; c16 < HDt / 16; ++c16) {
736	        int o = row * HDt + c16 * 16;
737	        if (valid) cp_async_16(sbase_addr + (uint32_t)o, src + c16 * 16);
738	        else       *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0);
