741	// Transpose one key column of the PLAIN [key][dv] staging tile into the swizzled K-major sVt[dv][key]
742	// (smem->smem; the global load latency is now hidden by cp.async, this pass only touches smem).
743	template <int HDVt>
744	__device__ __forceinline__ void transpose_v_smem8(__nv_fp8_e4m3* sVt, const __nv_fp8_e4m3* sVst, int key) {
745	#pragma unroll
746	    for (int c16 = 0; c16 < HDVt / 16; ++c16) {
747	        uint4 chunk = *reinterpret_cast<const uint4*>(sVst + key * HDVt + c16 * 16);
748	        const __nv_fp8_e4m3* cv = reinterpret_cast<const __nv_fp8_e4m3*>(&chunk);
749	#pragma unroll
750	        for (int e = 0; e < 16; ++e) sVt[koff8(c16 * 16 + e, key)] = cv[e];
751	    }
752	}
