784	__device__ __forceinline__ void gather_row_v(TC* sbase, uint32_t sbase_addr, int key,
785	                                             const TIn* src, bool valid) {
786	#pragma unroll
787	    for (int c8 = 0; c8 < HDVt / 8; ++c8) {
788	        int o = voffR<ROWS>(key, c8 * 8);
789	        if (!valid) { *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0); continue; }
790	        if constexpr (std::is_same<TIn, TC>::value) {
