793	#else
794	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(src + c8 * 8);
795	#endif
796	        } else {
797	            uint2 raw = *reinterpret_cast<const uint2*>(src + c8 * 8);   // 8 fp8 in ONE coalesced load
798	            const TIn* f = reinterpret_cast<const TIn*>(&raw);
799	            TC tmp[8];
800	#pragma unroll
801	            for (int e = 0; e < 8; ++e) tmp[e] = from_float<TC>(to_float<TIn>(f[e]));
