181	__device__ __forceinline__ uint64_t make_smem_desc(uint32_t a, uint32_t lbo, uint32_t sbo, uint32_t lt) {
182	    uint64_t d = 0;
183	    d |= (uint64_t)((a >> 4) & 0x3FFFu);
184	    d |= (uint64_t)((lbo >> 4) & 0x3FFFu) << 16;
185	    d |= (uint64_t)((sbo >> 4) & 0x3FFFu) << 32;
186	    d |= (uint64_t)(lt & 0x3u) << 62;
187	    return d;
188	}
189	__device__ __forceinline__ uint64_t desc_add(uint64_t base, uint32_t off) {
190	    uint32_t lo, hi;
191	    asm("mov.b64 {%0,%1}, %2;\n" : "=r"(lo), "=r"(hi) : "l"(base));
192	    lo += off;
193	    uint64_t r; asm("mov.b64 %0, {%1,%2};\n" : "=l"(r) : "r"(lo), "r"(hi));
194	    return r;
195	}
196	__device__ __forceinline__ uint64_t v_doff(int kb)  { return (uint64_t)(kb * 128); }
