217	template <typename T> __device__ __forceinline__ uint32_t pack_2x(float lo, float hi);
218	template <> __device__ __forceinline__ uint32_t pack_2x<__nv_bfloat16>(float lo, float hi) { return pack_bf16(lo, hi); }
219	template <> __device__ __forceinline__ uint32_t pack_2x<__half>(float lo, float hi) {
220	    __half a = __float2half_rn(lo), b = __float2half_rn(hi);
221	    uint16_t ua, ub; memcpy(&ua, &a, 2); memcpy(&ub, &b, 2);
