2038	// Build a 2D TMA tensor map over a paged KV cache [num_blocks, block_size, hkv, hd] viewed as
2039	// [num_blocks*block_size (rows), hkv*hd (cols)], box [block_size, 64] with 128B swizzle. The fast
2040	// path loads each page as 2 such boxes (cols [0,64),[64,128) of the head) -> composes byte-exactly
2041	// into the 128-row swizzled tile the wgmma consumer reads (see tma_probe16.cu).
2042	template <typename T> static constexpr CUtensorMapDataType tmap_dtype();
2043	template <> constexpr CUtensorMapDataType tmap_dtype<__nv_bfloat16>() { return CU_TENSOR_MAP_DATA_TYPE_BFLOAT16; }
2044	template <> constexpr CUtensorMapDataType tmap_dtype<__half>()        { return CU_TENSOR_MAP_DATA_TYPE_FLOAT16; }
2045	template <> constexpr CUtensorMapDataType tmap_dtype<__nv_fp8_e4m3>() { return CU_TENSOR_MAP_DATA_TYPE_UINT8; }
2046	
2047	// fp8 (1-byte) contiguous TMA map over [total_rows, heads, hd] viewed as [heads*hd, total_rows]. box
2048	// [128, rows]: 128 fp8 = one 128-Byte swizzle row, so a single box loads a full hd128 K/Q tile into
2049	// the koff8 layout (Swizzle<3,4,3>) the wgmma descriptor reads. swz=128B when `sw`, else NONE (the
2050	// plain V-staging tile that transpose_v_smem8 consumes row-major). Heads contiguous (stride(1)==hd).
2051	static CUtensorMap make_fp8_contig(const at::Tensor& t, int rows_box, bool sw) {
2052	    CUtensorMap map{};
2053	    int64_t total = t.size(0), heads = t.size(1), hd = t.size(2);
2054	    uint64_t gdim[2]    = {(uint64_t)(heads * hd), (uint64_t)total};
2055	    uint64_t gstride[1] = {(uint64_t)(t.stride(0))};                 // bytes per row (1-byte elems)
2056	    uint32_t bdim[2]    = {128u, (uint32_t)rows_box};
2057	    uint32_t estride[2] = {1u, 1u};
2058	    CUresult cr = cuTensorMapEncodeTiled(&map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 2, t.data_ptr(),
2059	        gdim, gstride, bdim, estride, CU_TENSOR_MAP_INTERLEAVE_NONE,
2060	        sw ? CU_TENSOR_MAP_SWIZZLE_128B : CU_TENSOR_MAP_SWIZZLE_NONE,
2061	        CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
2062	    TORCH_CHECK(cr == CUDA_SUCCESS, "cuTensorMapEncodeTiled (fp8) failed: ", (int)cr);
