2108	    uint64_t gdim[2]    = {(uint64_t)(hkv * hd), (uint64_t)total_k};
2109	    uint64_t gstride[1] = {(uint64_t)(t.stride(0) * (int64_t)sizeof(T))};   // bytes per key row
2110	    uint32_t bdim[2]    = {64u, (uint32_t)cn};
2111	    uint32_t estride[2] = {1u, 1u};
2112	    CUresult cr = cuTensorMapEncodeTiled(&map, tmap_dtype<T>(), 2, t.data_ptr(),
2113	        gdim, gstride, bdim, estride, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
2114	        CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
