2119	// Build a 3D TMA tensor map over packed-GQA Q [total_q, hq, hd], box [64, rep, CM/rep]. A single box
2120	// per (col-block bx, head-group hk, m_block) loads CM/rep tokens x rep heads x 64 cols into the SAME
2121	// swizzled [CM,64] tile the wgmma consumer reads: the box's row-major smem order (tok*rep+head)*64+d
2122	// equals koffR<CM>(tok*rep+head,d)'s pre-swizzle term, and SWIZZLE_128B is applied on the smem address
2123	// (period 8 rows) so it lands byte-exact -- this is the GQA analogue of the rep==1 contiguous Q box
2124	// (validated by correctness). Requires rep | CM and heads contiguous (stride(2)==1, stride(1)==hd).
2125	template <typename T>
2126	static CUtensorMap make_q_map_gqa(const at::Tensor& q, int rep, int cm) {
