2129	    uint64_t gdim[3]    = {(uint64_t)hd, (uint64_t)hq, (uint64_t)total_q};            // inner -> outer
2130	    uint64_t gstride[2] = {(uint64_t)(q.stride(1) * (int64_t)sizeof(T)),              // bytes per head
2131	                           (uint64_t)(q.stride(0) * (int64_t)sizeof(T))};             // bytes per token
2132	    uint32_t bdim[3]    = {64u, (uint32_t)rep, (uint32_t)(cm / rep)};
2133	    uint32_t estride[3] = {1u, 1u, 1u};
2134	    CUresult cr = cuTensorMapEncodeTiled(&map, tmap_dtype<T>(), 3, q.data_ptr(),
2135	        gdim, gstride, bdim, estride, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
2136	        CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
2137	    TORCH_CHECK(cr == CUDA_SUCCESS, "cuTensorMapEncodeTiled (gqa-q) failed: ", (int)cr);
