1858	    __nv_fp8_e4m3* sQ = reinterpret_cast<__nv_fp8_e4m3*>(pf_smem);
1859	    __nv_fp8_e4m3* sK0 = sQ + QBUF * CM * HDQK;
1860	    __nv_fp8_e4m3* sV0 = sK0 + STAGES * KSTRIDE;
1861	    __nv_fp8_e4m3* sP  = sV0 + STAGES * VSTRIDE;
