1866	    uint64_t* loaded = bars + 2 * STAGES;       // [STAGES] count NumProd (K + V-staging cp.async)
1867	    uint64_t* barQf = bars + 3 * STAGES;        // [QBUF] Q ready (producer -> consumers), count NumProd
1868	    uint64_t* barQe = bars + 3 * STAGES + QBUF; // [QBUF] Q free  (consumers -> producer), count NumCons
1869	    uint64_t* schF = bars + 3 * STAGES + 2 * QBUF;          // [SDEPTH] work ready (producer -> consumers)
1870	    uint64_t* schE = bars + 3 * STAGES + 2 * QBUF + SDEPTH; // [SDEPTH] slot free (consumers -> producer)
1871	    int* schW = reinterpret_cast<int*>(bars + 3 * STAGES + 2 * QBUF + 2 * SDEPTH);  // [SDEPTH] grabbed work idx
