1873	    const int tid = threadIdx.x;
1874	    if (tid == 0) {
1875	#pragma unroll
1876	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], NumProd); mbar_init(&empty[s], NumCons); mbar_init(&loaded[s], 1); }
1877	#pragma unroll
1878	        for (int s = 0; s < QBUF; ++s) { mbar_init(&barQf[s], NumProd); mbar_init(&barQe[s], NumCons); }
